// V15.7.1 retains the complete NTRIP controls in the current UI. The API already
// supports these values; keeping this renderer separate also makes the secret
// retention and numeric conversions explicit.
async function mountConfigurationV1561(signal){
  replace(main,skeleton("Loading configuration"));
  const config=await api.json("/api/config",{signal});
  const form=h("form",{class:"configuration-layout"});
  const fallbackValue=(config.wifi_networks||[]).map(item=>
    item.ssid+(item.password_set?"":"")).join("\n");
  const wifi=h("section",{class:"tool-card config-section"},
    h("p",{class:"kicker",text:"WI-FI CONNECTION"}),
    h("h2",{text:"Field network"}),
    configField(config,"wifi_ssid","SSID"),
    configField(config,"wifi_pass","Password","password",
      config.wifi_pass_set?"A password is saved.":"No password is saved."),
    h("label",{class:"field"},h("span",{text:"Fallback networks"}),
      h("textarea",{name:"wifi_networks",value:fallbackValue,
        placeholder:"SSID or SSID:password, one network per line"}),
      h("small",{text:"Existing passwords are retained when only the SSID is entered."})),
    h("div",{class:"inline-actions"},iconButton("Scan networks",async event=>{
      const button=event.currentTarget;button.disabled=true;
      try{
        state.className="notice";state.textContent=localText("Scanning for Wi-Fi networks …");
        let result=await api.json("/api/wifi-scan");
        for(let attempt=0;result.status==="pending"&&attempt<16;attempt++){
          await new Promise(resolve=>setTimeout(resolve,750));
          result=await api.json("/api/wifi-scan");
        }
        const options=(result.networks||[]).map(network=>
          ({value:network.ssid,label:`${network.ssid} · ${network.rssi} dBm`}));
        if(!options.length)throw new Error("No Wi-Fi networks were found.");
        const selected=await modal({title:"Visible Wi-Fi networks",
          fields:[{name:"ssid",label:"Network",type:"select",options}],submit:"Use network"});
        if(selected)form.elements.wifi_ssid.value=selected.ssid;
        state.className="notice ok";
        state.textContent=selected?"Network selected. Save to apply it.":"Wi-Fi scan complete.";
      }catch(error){state.className="notice critical";state.textContent=error.message;}
      finally{button.disabled=false;}
    },"secondary")));
  const enabled=h("select",{name:"ntrip_enabled"},
    h("option",{value:"1",selected:Boolean(config.ntrip_enabled),text:"Enabled"}),
    h("option",{value:"0",selected:!config.ntrip_enabled,text:"Disabled"}));
  const ntrip=h("section",{class:"tool-card config-section"},
    h("p",{class:"kicker",text:"NTRIP CASTER"}),h("h2",{text:"Correction source"}),
    h("label",{class:"field"},h("span",{text:"NTRIP client"}),enabled),
    h("h3",{text:"Primary caster"}),
    configField(config,"ntrip_host","Host"),
    configField(config,"ntrip_port","Port","number"),
    configField(config,"ntrip_mount","Mountpoint"),
    configField(config,"ntrip_user","Username"),
    configField(config,"ntrip_pass","Password","password",
      config.ntrip_pass_set?"A password is saved.":"No password is saved."),
    h("h3",{text:"Fallback caster (optional)"}),
    configField(config,"ntrip_fallback_host","Host"),
    configField(config,"ntrip_fallback_port","Port","number"),
    configField(config,"ntrip_fallback_mount","Mountpoint"),
    configField(config,"ntrip_fallback_user","Username"),
    configField(config,"ntrip_fallback_pass","Password","password",
      config.ntrip_fallback_pass_set?"A password is saved.":"No password is saved."),
    h("small",{text:"The fallback is used automatically when configured and the primary caster is unavailable."}));
  const state=h("p",{class:"notice",role:"status",
    text:"Changes are validated before the receiver restarts."});
  const save=iconButton("Save and verify configuration",()=>{},"primary");save.type="submit";
  form.append(wifi,ntrip,h("section",{class:"tool-card config-section"},
    h("p",{class:"kicker",text:"BACKUP & RESTORE"}),h("div",{class:"inline-actions"},
      h("a",{class:"btn secondary",href:"/api/config/backup",text:"Download configuration"}),
      iconButton("Restore backup",restoreConfiguration,"secondary"))),state,save);
  form.addEventListener("submit",async event=>{
    event.preventDefault();save.disabled=true;state.className="notice";
    state.textContent="Validating and staging configuration …";
    const values=Object.fromEntries(new FormData(form).entries());
    const saved=new Map((config.wifi_networks||[]).map(item=>[item.ssid,item]));
    values.ntrip_enabled=values.ntrip_enabled==="1";
    values.ntrip_port=Number(values.ntrip_port);
    values.ntrip_fallback_port=Number(values.ntrip_fallback_port);
    values.wifi_networks=String(values.wifi_networks||"").split(/\r?\n/).map(line=>{
      line=line.trim();if(!line)return null;const split=line.indexOf(":");
      if(split>=0)return{ssid:line.slice(0,split).trim(),password:line.slice(split+1)};
      const existing=saved.get(line);
      return{ssid:line,password_set:Boolean(existing&&existing.password_set)};
    }).filter(Boolean);
    try{
      await api.put("/api/config",values);state.className="notice ok";
      state.textContent="Configuration staged. Applying and reconnecting …";
      try{await api.post("/api/config/apply",{});}catch(_){}
      await waitForConfigResult(state,save);
    }catch(error){state.className="notice critical";state.textContent=error.message;save.disabled=false;}
  });
  replace(main,pageIntro("NETWORKS & CORRECTIONS","Configuration",
    "Changing Wi-Fi may temporarily disconnect this browser."),form);
  setConnection("Configuration loaded","ok");
}
mountConfiguration=mountConfigurationV1561;

